solution.code:
public class Main {
    public static void main(String[] args) {
        Playable song = new Song("Imagine");
        song.play();
    }
}

interface Playable {
    void play();
}

class Song implements Playable {
    private final String title;

    Song(String title) {
        this.title = title;
    }

    public void play() {
        System.out.println("Playing " + title);
    }
}
